export const blocks: readonly LiturgyBlock[] = [
  {"id": "ru-mol-0001", "section": "service", "who": "rubric", "text": "Глас 6-й"},
  {"id": "ru-mol-0002", "section": "service", "who": "rubric", "text": "Песнь 1"},
  {"id": "ru-mol-0003", "section": "service", "who": "rubric", "text": "Ирмос: Яко по суху пешешествовав Израиль, по бездне стопами, гонителя фараона видя потопляема, Богу победную песнь поим, вопияше."},
  {"id": "ru-mol-0004", "section": "service", "who": "reader", "text": "Перевод: Как по суше прошел Израиль по бездне стопами, и взывал, гонителя фараона видя утопавшим: «Богу победную песнь воспоем!»"},
  {"id": "ru-mol-0005", "section": "service", "who": "rubric", "text": "Припев: Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0006", "section": "service", "who": "rubric", "text": "Ныне приступих аз грешный и обремененный к Тебе, Владыце и Богу моему; не смею же взирати на небо, токмо молюся, глаголя: даждь ми, Господи, ум, да плачуся дел моих горько."},
  {"id": "ru-mol-0007", "section": "service", "who": "reader", "text": "Ныне приступил я, грешный и обременённый, к Тебе, Владыке и Богу моему; но не смею взирать на небо, только молю, возглашая: «Дай мне, Господи, разум, чтобы оплакивал я дела мои горько!»"},
  {"id": "ru-mol-0008", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0009", "section": "service", "who": "rubric", "text": "О, горе мне грешному! Паче всех человек окаянен есмь, покаяния несть во мне; даждь ми, Господи, слезы, да плачуся дел моих горько."},
  {"id": "ru-mol-0010", "section": "service", "who": "reader", "text": "О, горе мне, грешному! Более всех людей окаянен я: покаяния нет во мне. Дай мне, Господи, слёзы, чтобы оплакивал я дела мои горько!"},
  {"id": "ru-mol-0011", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Безумне, окаянне человече, в лености время губиши; помысли житие твое, и обратися ко Господу Богу, и плачися о делех твоих горько."},
  {"id": "ru-mol-0012", "section": "service", "who": "reader", "text": "Слава Отцу, и Сыну, и Святому Духу. Безумный, окаянный человек, ты время в лености губишь! Помысли о жизни своей и обратись ко Господу Богу, и плачь о делах своих горько!"},
  {"id": "ru-mol-0013", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Мати Божия Пречистая, воззри на мя грешнаго, и от сети диаволи избави мя, и на путь покаяния настави мя, да плачуся дел моих горько."},
  {"id": "ru-mol-0014", "section": "service", "who": "reader", "text": "И ныне, и всегда, и во веки веков, аминь. Матерь Божия Пречистая! Воззри на меня, грешного, и от сети диавола избавь меня, и на путь покаяния направь меня, чтобы оплакивал я дела мои горько!"},
  {"id": "ru-mol-0015", "section": "service", "who": "rubric", "text": "Песнь 3"},
  {"id": "ru-mol-0016", "section": "service", "who": "rubric", "text": "Ирмос: Несть свят, якоже Ты, Господи Боже мой, вознесый рог верных Твоих, Блаже, и утвердивый нас на камени исповедания Твоего."},
  {"id": "ru-mol-0017", "section": "service", "who": "reader", "text": "Нет святого, как Ты, Господи Боже мой, возвысивший верных Тебе, Благой, и утвердивший нас на камне исповедания Твоего."},
  {"id": "ru-mol-0018", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0019", "section": "service", "who": "rubric", "text": "Внегда поставлени будут престоли на судищи страшнем, тогда всех человек дела обличатся; горе тамо будет грешным, в муку отсылаемым; и то ведущи, душе моя, покайся от злых дел твоих."},
  {"id": "ru-mol-0020", "section": "service", "who": "reader", "text": "Когда поставлены будут престолы на Страшном Суде, тогда всех людей дела обличатся; горе там будет грешным, в муку отсылаемым! И зная это, душа моя, покайся в злых делах твоих!"},
  {"id": "ru-mol-0021", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0022", "section": "service", "who": "rubric", "text": "Праведницы возрадуются, а грешнии восплачутся, тогда никтоже возможет помощи нам, но дела наша осудят нас, темже прежде конца покайся от злых дел твоих."},
  {"id": "ru-mol-0023", "section": "service", "who": "reader", "text": "Праведники возрадуются, а грешники возрыдают: тогда никто не сможет помочь нам, но дела наши осудят нас. Потому прежде конца покайся в злых делах твоих!"},
  {"id": "ru-mol-0024", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Увы мне великогрешному, иже делы и мысльми осквернився, ни капли слез имею от жестосердия; ныне возникни от земли, душе моя, и покайся от злых дел твоих."},
  {"id": "ru-mol-0025", "section": "service", "who": "reader", "text": "Увы мне, многогрешному! Я, делами и мыслями осквернившись, ни капли слёз не имею от жестокосердия! Ныне воспрянь от земли, душа моя, и покайся в злых делах твоих!"},
  {"id": "ru-mol-0026", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Се, взывает, Госпоже, Сын Твой, и поучает нас на доброе, аз же грешный добра всегда бегаю; но Ты, Милостивая, помилуй мя, да покаюся от злых моих дел."},
  {"id": "ru-mol-0027", "section": "service", "who": "reader", "text": "Вот, взывает, Госпожа, Сын Твой и нас научает доброму; я же, грешный, всегда бегу от добра! Но Ты, Милостивая, помилуй меня, чтобы я раскаялся в делах моих злых!"},
  {"id": "ru-mol-0028", "section": "service", "who": "rubric", "text": "Седален, глас 6-й"},
  {"id": "ru-mol-0029", "section": "service", "who": "rubric", "text": "Помышляю день страшный и плачуся деяний моих лукавых: како отвещаю Безсмертному Царю, или коим дерзновением воззрю на Судию, блудный аз? Благоутробный Отче, Сыне Единородный и Душе Святый, помилуй мя."},
  {"id": "ru-mol-0030", "section": "service", "who": "reader", "text": "Помышляю о дне страшном и плачу о деяниях моих лукавых, как отвечу Бессмертному Царю? И как дерзну воззреть на Судию, я, блудный? Милосердный Отец, Сын Единородный, Дух Святой, помилуй меня."},
  {"id": "ru-mol-0031", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу, и ныне, и присно, и во веки веков, аминь."},
  {"id": "ru-mol-0032", "section": "service", "who": "rubric", "text": "Богородичен"},
  {"id": "ru-mol-0033", "section": "service", "who": "rubric", "text": "Связан многими ныне пленицами грехов и содержим лютыми страстьми и бедами, к Тебе прибегаю, моему спасению, и вопию: помози ми, Дево, Мати Божия."},
  {"id": "ru-mol-0034", "section": "service", "who": "reader", "text": "Ныне, связанный многими узами грехов и теснимый лютыми страданиями и бедами, к Тебе прибегаю, моему спасению, и взываю: «Помоги мне, Дева, Матерь Божия!»"},
  {"id": "ru-mol-0035", "section": "service", "who": "rubric", "text": "Песнь 4"},
  {"id": "ru-mol-0036", "section": "service", "who": "rubric", "text": "Ирмос: Христос моя сила, Бог и Господь, честная Церковь боголепно поет, взывающи от смысла чиста, о Господе празднующи."},
  {"id": "ru-mol-0037", "section": "service", "who": "reader", "text": "Христос моя сила, Бог и Господь, святая Церковь благоговейно поёт, взывая, от чистого разума в Господе торжествуя."},
  {"id": "ru-mol-0038", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0039", "section": "service", "who": "rubric", "text": "Широк путь зде и угодный сласти творити, но горько будет в последний день, егда душа от тела разлучатися будет: блюдися от сих, человече, Царствия ради Божия."},
  {"id": "ru-mol-0040", "section": "service", "who": "reader", "text": "Широк путь здесь и легко делать приятное, но горько будет в последний день, когда душа с телом разлучаться будет! Храни себя от того, человек, ради Царства Божия!"},
  {"id": "ru-mol-0041", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0042", "section": "service", "who": "rubric", "text": "Почто убогаго обидиши, мзду наемничу удержуеши, брата твоего не любиши, блуд и гордость гониши? Остави убо сия, душе моя, и покайся Царствия ради Божия."},
  {"id": "ru-mol-0043", "section": "service", "who": "reader", "text": "Зачем бедного обижаешь, плату работника удерживаешь, брата своего не любишь, к блуду и гордыне стремишься? Оставь же все это, душа моя, и покайся ради Царствия Божия!"},
  {"id": "ru-mol-0044", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. О, безумный человече, доколе углебаеши, яко пчела, собирающи богатство твое? Вскоре бо погибнет, яко прах и пепел: но более взыщи Царствия Божия."},
  {"id": "ru-mol-0045", "section": "service", "who": "reader", "text": "О безумный человек! Доколе будешь суетиться, словно пчела, собирая богатство своё? Ведь вскоре погибнет оно, как прах и пепел; но ты прежде взыщи Царствия Божия."},
  {"id": "ru-mol-0046", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Госпоже Богородице, помилуй мя грешнаго, и в добродетели укрепи, и соблюди мя, да наглая смерть не похитит мя неготоваго, и доведи мя, Дево, Царствия Божия."},
  {"id": "ru-mol-0047", "section": "service", "who": "reader", "text": "Госпожа Богородица! Помилуй меня, грешного, и в добродетели укрепи и сохрани меня, чтобы внезапная смерть не похитила меня, неготового, и доведи меня, Дева, до Царствия Божия!"},
  {"id": "ru-mol-0048", "section": "service", "who": "rubric", "text": "Песнь 5"},
  {"id": "ru-mol-0049", "section": "service", "who": "rubric", "text": "Ирмос: Божиим светом Твоим, Блаже, утренюющих Ти души любовию озари, молюся, Тя ведети, Слове Божий, истиннаго Бога, от мрака греховнаго взывающа."},
  {"id": "ru-mol-0050", "section": "service", "who": "reader", "text": "Божественным светом Своим, Благой, души с рассвета к Тебе стремящихся любовью озари, молюсь я, чтобы знать Тебя, Слово Божие, истинного Бога, от мрака грехов к Себе призывающего."},
  {"id": "ru-mol-0051", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0052", "section": "service", "who": "rubric", "text": "Воспомяни, окаянный человече, како лжам, клеветам, разбою, немощем, лютым зверем, грехов ради порабощен еси; душе моя грешная, того ли восхотела еси?"},
  {"id": "ru-mol-0053", "section": "service", "who": "reader", "text": "Вспомни, окаянный человек, как лжи, клевете, разбою, болезням, словно лютым зверям, порабощён ты по грехам своим! Душа моя грешная, того ли желала ты?"},
  {"id": "ru-mol-0054", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0055", "section": "service", "who": "rubric", "text": "Трепещут ми уди, всеми бо сотворих вину: очима взираяй, ушима слышай, языком злая глаголяй, всего себе геенне предаяй; душе моя грешная, сего ли восхотела еси?"},
  {"id": "ru-mol-0056", "section": "service", "who": "reader", "text": "Трепещут члены тела моего, ибо я всеми ими провинился: глазами взирая, ушами слушая, языком говоря злое, всего себя геенне предал! Душа моя грешная, этого ли желала ты?"},
  {"id": "ru-mol-0057", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Блудника и разбойника кающася приял еси, Спасе, аз же един леностию греховною отягчихся и злым делом поработихся, душе моя грешная, сего ли восхотела еси?"},
  {"id": "ru-mol-0058", "section": "service", "who": "reader", "text": "Блудного сына и разбойника кающегося принял Ты, Спаситель; но лишь я один греховной ленью отягчён и злым делам порабощён! Душа моя грешная, этого ли желала ты?"},
  {"id": "ru-mol-0059", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Дивная и скорая помощнице всем человеком, Мати Божия, помози мне недостойному, душа бо моя грешная того восхоте."},
  {"id": "ru-mol-0060", "section": "service", "who": "reader", "text": "Дивная и скорая помощница всем людям, Матерь Божия! Помоги мне, недостойному, ибо душа моя грешная того возжелала!"},
  {"id": "ru-mol-0061", "section": "service", "who": "rubric", "text": "Песнь 6"},
  {"id": "ru-mol-0062", "section": "service", "who": "rubric", "text": "Ирмос: Житейское море, воздвизаемое зря напастей бурею, к тихому пристанищу Твоему притек, вопию Ти: возведи от тли живот мой, Многомилостиве."},
  {"id": "ru-mol-0063", "section": "service", "who": "reader", "text": "Житейское море видя, поднимающееся волнами искушений, я, к тихой пристани Твоей стремясь, взываю Тебе: «Возведи от погибели жизнь мою, Многомилостивый!»"},
  {"id": "ru-mol-0064", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0065", "section": "service", "who": "rubric", "text": "Житие на земли блудно пожих и душу во тьму предах, ныне убо молю Тя, Милостивый Владыко: свободи мя от работы сея вражия, и даждь ми разум творити волю Твою."},
  {"id": "ru-mol-0066", "section": "service", "who": "reader", "text": "Жизнь земную я блудно прожил и душу во тьму предал; ныне же молю Тебя, милостивый Владыка: освободи меня от этого рабства врагу и дай мне разум исполнять волю Твою!"},
  {"id": "ru-mol-0067", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0068", "section": "service", "who": "rubric", "text": "Кто творит таковая, якоже аз? Якоже бо свиния лежит в калу, тако и аз греху служу. Но Ты, Господи, исторгни мя от гнуса сего и даждь ми сердце творити заповеди Твоя."},
  {"id": "ru-mol-0069", "section": "service", "who": "reader", "text": "Кто совершает такое, как я? Ибо как свинья лежит в грязи, так же и я греху служу. Но Ты, Господи, исторгни меня из гнусности той и дай мне сердце, готовое исполнять заповеди Твои!"},
  {"id": "ru-mol-0070", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Воспряни, окаянный человече, к Богу, воспомянув своя согрешения, припадая ко Творцу, слезя и стеня; Той же, яко милосерд, даст ти ум знати волю Свою."},
  {"id": "ru-mol-0071", "section": "service", "who": "reader", "text": "Воспрянь к Богу, окаянный человек, вспомнив свои согрешения, припадая ко Творцу, проливая слезы и стеная! Он же, как милосердный, даст тебе ум познать волю Его!"},
  {"id": "ru-mol-0072", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Богородице Дево, от видимаго и невидимаго зла сохрани мя, Пречистая, и приими молитвы моя, и донеси я Сыну Твоему, да даст ми ум творити волю Его."},
  {"id": "ru-mol-0073", "section": "service", "who": "reader", "text": "Богородица Дева! От видимого и невидимого зла сохрани меня, Пречистая, и прими прошения мои, и передай их Сыну Твоему, да даст мне ум исполнять волю Его!"},
  {"id": "ru-mol-0074", "section": "service", "who": "rubric", "text": "Кондак"},
  {"id": "ru-mol-0075", "section": "service", "who": "rubric", "text": "Душе моя, почто грехами богатееши, почто волю диаволю твориши, в чесом надежду полагаеши? Престани от сих и обратися к Богу с плачем, зовущи: милосерде Господи, помилуй мя грешнаго."},
  {"id": "ru-mol-0076", "section": "service", "who": "reader", "text": "Душа моя! Зачем грехами богатеешь? Зачем волю диавола исполняешь? На что надежду возлагаешь? Перестань так поступать и обратись к Богу, с плачем взывая: «Милосердный Господи, помилуй меня, грешного!»"},
  {"id": "ru-mol-0077", "section": "service", "who": "rubric", "text": "Икос"},
  {"id": "ru-mol-0078", "section": "service", "who": "rubric", "text": "Помысли, душе моя, горький час смерти и страшный суд Творца твоего и Бога: Ангели бо грознии поймут тя, душе, и в вечный огнь введут: убо прежде смерти покайся, вопиющи: Господи, помилуй мя грешнаго."},
  {"id": "ru-mol-0079", "section": "service", "who": "reader", "text": "Помысли, душа моя, о горьком часе смерти и о Страшном Суде Творца твоего и Бога. Ведь тогда Ангелы грозные возьмут тебя, душа, и в вечный огонь введут. Так покайся же прежде смерти, взывая: «Господи, помилуй меня, грешного!»"},
  {"id": "ru-mol-0080", "section": "service", "who": "rubric", "text": "Песнь 7"},
  {"id": "ru-mol-0081", "section": "service", "who": "rubric", "text": "Ирмос: Росодательну убо пещь содела Ангел преподобным отроком, халдеи же опаляющее веление Божие, мучителя увеща вопити: благословен еси, Боже отец наших."},
  {"id": "ru-mol-0082", "section": "service", "who": "reader", "text": "Росоносною соделал печь Ангел для благочестивых отроков, а Божие веление, халдеев опалявшее, мучителя заставило взывать: «Благословен Ты, Боже отцов наших!»"},
  {"id": "ru-mol-0083", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0084", "section": "service", "who": "rubric", "text": "Не надейся, душе моя, на тленное богатство и на неправедное собрание, вся бо сия не веси кому оставиши, но возопий: помилуй мя, Христе Боже, недостойнаго."},
  {"id": "ru-mol-0085", "section": "service", "who": "reader", "text": "Не полагайся, душа моя, на тленное богатство и на неправедное стяжание; ведь не знаешь ты, кому всё это оставишь, но воззови: «Помилуй меня, Христе Боже, недостойного!»"},
  {"id": "ru-mol-0086", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0087", "section": "service", "who": "rubric", "text": "Не уповай, душе моя, на телесное здравие и на скоромимоходящую красоту, видиши бо, яко сильнии и младии умирают; но возопий: помилуй мя, Христе Боже, недостойнаго."},
  {"id": "ru-mol-0088", "section": "service", "who": "reader", "text": "Не надейся, душа моя, на телесное здоровье и на скоро преходящую красоту; ведь ты видишь, как сильные и молодые умирают, но воззови: «Помилуй меня, Христе Боже, недостойного!»"},
  {"id": "ru-mol-0089", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Воспомяни, душе моя, вечное житие, Царство Небесное, уготованное святым, и тьму кромешную и гнев Божий злым, и возопий: помилуй мя, Христе Боже, недостойнаго."},
  {"id": "ru-mol-0090", "section": "service", "who": "reader", "text": "Вспомни, душа моя, о вечной жизни и о Царстве Небесном, уготованном святым, и о тьме кромешной и гневе Божием – злым, и воззови: «Помилуй меня, Христе Боже, недостойного!»"},
  {"id": "ru-mol-0091", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Припади, душе моя, к Божией Матери и помолися Той, есть бо скорая помощница кающимся, умолит Сына Христа Бога, и помилует мя недостойнаго."},
  {"id": "ru-mol-0092", "section": "service", "who": "reader", "text": "Припади, душа моя, к Божией Матери и помолись Ей, ибо Она, скорая Помощница кающимся, умолит Сына, Христа Бога, и Он помилует меня, недостойного."},
  {"id": "ru-mol-0093", "section": "service", "who": "rubric", "text": "Песнь 8"},
  {"id": "ru-mol-0094", "section": "service", "who": "rubric", "text": "Ирмос: Из пламене преподобным росу источил еси и праведнаго жертву водою попалил еси: вся бо твориши, Христе, токмо еже хотети. Тя превозносим во вся веки."},
  {"id": "ru-mol-0095", "section": "service", "who": "reader", "text": "Из пламени Ты для благочестивых росу источил, и жертву праведника водою попалил: ибо Ты все совершаешь, Христе, одним Своим хотением. Тебя мы превозносим во все века."},
  {"id": "ru-mol-0096", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0097", "section": "service", "who": "rubric", "text": "Како не имам плакатися, егда помышляю смерть, видех бо во гробе лежаща брата моего, безславна и безобразна? Что убо чаю, и на что надеюся? Токмо даждь ми, Господи, прежде конца покаяние. (Дважды)"},
  {"id": "ru-mol-0098", "section": "service", "who": "reader", "text": "Как мне не плакать, когда помышляю о смерти! Ибо видел я лежащего во гробе брата своего бесславным и безобразным. Чего же я жду и на что надеюсь? Только дай мне, Господи, прежде конца покаяние!"},
  {"id": "ru-mol-0099", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Верую, яко приидеши судити живых и мертвых, и вси во своем чину станут, старии и младии, владыки и князи, девы и священницы; где обрящуся аз? Сего ради вопию: даждь ми, Господи, прежде конца покаяние."},
  {"id": "ru-mol-0100", "section": "service", "who": "reader", "text": "Верую, что Ты придёшь судить живых и мёртвых, и все по чину своему станут: старые и молодые, владыки и князья, девы и священники. Но где окажусь я? Потому взываю: «Дай мне, Господи, прежде конца покаяние!»"},
  {"id": "ru-mol-0101", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Пречистая Богородице, приими недостойную молитву мою и сохрани мя от наглыя смерти, и даруй ми прежде конца покаяние."},
  {"id": "ru-mol-0102", "section": "service", "who": "reader", "text": "Пречистая Богородица! Прими недостойную молитву мою, и сохрани меня от внезапной смерти и даруй мне прежде конца покаяние!"},
  {"id": "ru-mol-0103", "section": "service", "who": "rubric", "text": "Песнь 9"},
  {"id": "ru-mol-0104", "section": "service", "who": "rubric", "text": "Ирмос: Бога человеком невозможно видети, на Негоже не смеют чини Ангельстии взирати; Тобою же, Всечистая, явися человеком Слово Воплощенно, Егоже величающе, с небесными вои Тя ублажаем."},
  {"id": "ru-mol-0105", "section": "service", "who": "reader", "text": "Невозможно людям увидеть Бога, на Которого не смеют и сонмы Ангелов взирать; но чрез Тебя, Всечистая, стало видимым для смертных Слово воплощённое. Его величая, мы вместе с небесными воинствами Тебя восхваляем."},
  {"id": "ru-mol-0106", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0107", "section": "service", "who": "rubric", "text": "Ныне к вам прибегаю, Ангели, Архангели и вся небесныя силы, у Престола Божия стоящии, молитеся ко Творцу своему, да избавит душу мою от муки вечныя."},
  {"id": "ru-mol-0108", "section": "service", "who": "reader", "text": "Ныне к вам прибегаю, Ангелы, Архангелы и все небесные Силы, у престола Божия стоящие: молитесь Творцу своему, да избавит Он душу мою от муки вечной!"},
  {"id": "ru-mol-0109", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0110", "section": "service", "who": "rubric", "text": "Ныне плачуся к вам, святии патриарси, царие и пророцы, апостоли и святителие и вси избраннии Христовы: помозите ми на суде, да спасет душу мою от силы вражия."},
  {"id": "ru-mol-0111", "section": "service", "who": "reader", "text": "Ныне плачу пред вами, святые праотцы, цари и пророки, апостолы и святители, и все избранники Христовы: помогите мне на Суде, да спасет Господь душу мою от силы вражией!"},
  {"id": "ru-mol-0112", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Ныне к вам воздежу руце, святии мученицы, пустынницы, девственницы, праведницы и вси святии, молящиися ко Господу за весь мир, да помилует мя в час смерти моея."},
  {"id": "ru-mol-0113", "section": "service", "who": "reader", "text": "Ныне к вам возношу руки, святые мученики, пустынники, девственники, праведники и все святые, молящиеся ко Господу за весь мир, да помилует Он меня в час смерти моей!"},
  {"id": "ru-mol-0114", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Мати Божия, помози ми, на Тя сильне надеющемуся, умоли Сына Своего, да поставит мя недостойнаго одесную Себе, егда сядет судяй живых и мертвых, аминь."},
  {"id": "ru-mol-0115", "section": "service", "who": "reader", "text": "Матерь Божия, помоги мне, на Тебя крепко надеющемуся, умоли Сына Своего, да поставит Он меня, недостойного, справа от Себя, когда сядет судить живых и мёртвых! Аминь."},
  {"id": "ru-mol-0116", "section": "service", "who": "rubric", "text": "Молитва"},
  {"id": "ru-mol-0117", "section": "service", "who": "reader", "text": "Владыка Христос Бог, страданиями Твоими страсти мои исцеливший и ранами Твоими язвы мои уврачевавший! Даруй мне, много пред Тобою согрешившему, слёзы сокрушения о грехах. Даруй моему телу принять благоухание животворящего Тела Твоего, и подай душе моей сладость Твоей драгоценной Крови вместо горечи, которой напоил меня враг. Возвысь к Тебе мой ум, к земле поникший, и возведи из пропасти погибельной. Ибо нет во мне покаяния, нет во мне сокрушения, нет во мне слёз утешительных, приводящих чад к Отчему дому. Омрачился я разумом в житейских страстях, не могу воззреть на Тебя в страдании, не могу согреться слезами любви к Тебе! Но, Владыка Господь Иисус Христос, Сокровищница благ! Даруй мне покаяние полное и сердце, с любовью трудящееся в поисках Тебя; даруй мне благодать Твою и обнови во мне черты Твоего образа. Я оставил Тебя — не оставь меня. Выйди искать меня, приведи на Своё пастбище и сопричисли меня к овцам Твоего избранного стада, напитай меня вместе с ними от хлеба Божественных Твоих Таинств, по молитвам Пречистой Твоей Матери и всех святых Твоих. Аминь."},
  {"id": "ru-mol-0118", "section": "service", "who": "rubric", "text": "Песнь 1"},
  {"id": "ru-mol-0119", "section": "service", "who": "rubric", "text": "Ирмос: Яко по суху пешешествовав Израиль, по бездне стопами, гонителя фараона видя потопляема, Богу победную песнь поим, вопияше."},
  {"id": "ru-mol-0120", "section": "service", "who": "reader", "text": "Как по суше прошел Израиль по бездне стопами, и взывал, гонителя фараона видя утопавшим: «Богу победную песнь воспоем!»"},
  {"id": "ru-mol-0121", "section": "service", "who": "rubric", "text": "Припев: Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0122", "section": "service", "who": "rubric", "text": "Ныне приступих аз грешная и обремененная к Тебе, Владыце и Богу моему; не смею же взирати на небо, токмо молюся, глаголющи: даждь ми, Господи, ум, да плачуся дел моих горько."},
  {"id": "ru-mol-0123", "section": "service", "who": "reader", "text": "Ныне приступила я, грешная и обременённая, к Тебе, Владыке и Богу моему; но не смею взирать на небо, только молю, возглашая: «Дай мне, Господи, разум, чтобы оплакивала я дела мои горько!»"},
  {"id": "ru-mol-0124", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0125", "section": "service", "who": "rubric", "text": "О, горе мне грешной! Паче всех человек окаянна есмь, покаяния несть во мне; даждь ми, Господи, слезы, да плачуся дел моих горько."},
  {"id": "ru-mol-0126", "section": "service", "who": "reader", "text": "О, горе мне, грешной! Более всех людей окаянна я: покаяния нет во мне. Дай мне, Господи, слёзы, чтобы оплакивала я дела мои горько!"},
  {"id": "ru-mol-0127", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Безумне, окаянне человече, в лености время губиши; помысли житие твое, и обратися ко Господу Богу, и плачися о делех твоих горько."},
  {"id": "ru-mol-0128", "section": "service", "who": "reader", "text": "Слава Отцу, и Сыну, и Святому Духу. Безумный, окаянный человек, ты время в лености губишь! Помысли о жизни своей и обратись ко Господу Богу, и плачь о делах своих горько!"},
  {"id": "ru-mol-0129", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Мати Божия Пречистая, воззри на мя грешную, и от сети диаволи избави мя, и на путь покаяния настави мя, да плачуся дел моих горько."},
  {"id": "ru-mol-0130", "section": "service", "who": "reader", "text": "И ныне, и всегда, и во веки веков, аминь. Матерь Божия Пречистая! Воззри на меня, грешную, и от сети диавола избавь меня, и на путь покаяния направь меня, чтобы оплакивала я дела мои горько!"},
  {"id": "ru-mol-0131", "section": "service", "who": "rubric", "text": "Песнь 3"},
  {"id": "ru-mol-0132", "section": "service", "who": "rubric", "text": "Ирмос: Несть свят, якоже Ты, Господи Боже мой, вознесый рог верных Твоих, Блаже, и утвердивый нас на камени исповедания Твоего."},
  {"id": "ru-mol-0133", "section": "service", "who": "reader", "text": "Нет святого, как Ты, Господи Боже мой, возвысивший верных Тебе, Благой, и утвердивший нас на камне исповедания Твоего."},
  {"id": "ru-mol-0134", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0135", "section": "service", "who": "rubric", "text": "Внегда поставлени будут престоли на судищи страшнем, тогда всех человек дела обличатся; горе тамо будет грешным, в муку отсылаемым; и то ведущи, душе моя, покайся от злых дел твоих."},
  {"id": "ru-mol-0136", "section": "service", "who": "reader", "text": "Когда поставлены будут престолы на Страшном Суде, тогда всех людей дела обличатся; горе там будет грешным, в муку отсылаемым! И зная это, душа моя, покайся в злых делах твоих!"},
  {"id": "ru-mol-0137", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0138", "section": "service", "who": "rubric", "text": "Праведницы возрадуются, а грешнии восплачутся, тогда никтоже возможет помощи нам, но дела наша осудят нас, темже прежде конца покайся от злых дел твоих."},
  {"id": "ru-mol-0139", "section": "service", "who": "reader", "text": "Праведники возрадуются, а грешники возрыдают: тогда никто не сможет помочь нам, но дела наши осудят нас. Потому прежде конца покайся в злых делах твоих!"},
  {"id": "ru-mol-0140", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Увы мне великогрешной, яже делы и мысльми осквернившися, ни капли слез имею от жестосердия; ныне возникни от земли, душе моя, и покайся от злых дел твоих."},
  {"id": "ru-mol-0141", "section": "service", "who": "reader", "text": "Увы мне, многогрешной! Я, делами и мыслями осквернившись, ни капли слёз не имею от жестокосердия! Ныне воспрянь от земли, душа моя, и покайся в злых делах твоих!"},
  {"id": "ru-mol-0142", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Се, взывает, Госпоже, Сын Твой, и поучает нас на доброе, аз же грешная добра всегда бегаю; но Ты, Милостивая, помилуй мя, да покаюся от злых моих дел."},
  {"id": "ru-mol-0143", "section": "service", "who": "reader", "text": "Вот, взывает, Госпожа, Сын Твой и нас научает доброму; я же, грешная, всегда бегу от добра! Но Ты, Милостивая, помилуй меня, чтобы я раскаялась в делах моих злых!"},
  {"id": "ru-mol-0144", "section": "service", "who": "rubric", "text": "Седален, глас 6-й"},
  {"id": "ru-mol-0145", "section": "service", "who": "rubric", "text": "Помышляю день страшный и плачуся деяний моих лукавых: како отвещаю Безсмертному Царю, или коим дерзновением воззрю на Судию, блудная аз? Благоутробный Отче, Сыне Единородный и Душе Святый, помилуй мя."},
  {"id": "ru-mol-0146", "section": "service", "who": "reader", "text": "Помышляю о дне страшном и плачу о деяниях моих лукавых, как отвечу Бессмертному Царю? И как дерзну воззреть на Судию, я, блудная? Милосердный Отец, Сын Единородный, Дух Святой, помилуй меня."},
  {"id": "ru-mol-0147", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу, и ныне, и присно, и во веки веков, аминь."},
  {"id": "ru-mol-0148", "section": "service", "who": "rubric", "text": "Богородичен"},
  {"id": "ru-mol-0149", "section": "service", "who": "rubric", "text": "Связана многими ныне пленицами грехов и содержима лютыми страстьми и бедами, к Тебе прибегаю, моему спасению, и вопию: помози ми, Дево, Мати Божия."},
  {"id": "ru-mol-0150", "section": "service", "who": "reader", "text": "Ныне, связанная многими узами грехов и теснимая лютыми страданиями и бедами, к Тебе прибегаю, моему спасению, и взываю: «Помоги мне, Дева, Матерь Божия!»"},
  {"id": "ru-mol-0151", "section": "service", "who": "rubric", "text": "Песнь 4"},
  {"id": "ru-mol-0152", "section": "service", "who": "rubric", "text": "Ирмос: Христос моя сила, Бог и Господь, честная Церковь боголепно поет, взывающи от смысла чиста, о Господе празднующи."},
  {"id": "ru-mol-0153", "section": "service", "who": "reader", "text": "Христос моя сила, Бог и Господь, святая Церковь благоговейно поёт, взывая, от чистого разума в Господе торжествуя."},
  {"id": "ru-mol-0154", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0155", "section": "service", "who": "rubric", "text": "Широк путь зде и угодный сласти творити, но горько будет в последний день, егда душа от тела разлучатися будет: блюдися от сих, человече, Царствия ради Божия."},
  {"id": "ru-mol-0156", "section": "service", "who": "reader", "text": "Широк путь здесь и легко делать приятное, но горько будет в последний день, когда душа с телом разлучаться будет! Храни себя от того, человек, ради Царства Божия!"},
  {"id": "ru-mol-0157", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0158", "section": "service", "who": "rubric", "text": "Почто убогаго обидиши, мзду наемничу удержуеши, брата твоего не любиши, блуд и гордость гониши? Остави убо сия, душе моя, и покайся Царствия ради Божия."},
  {"id": "ru-mol-0159", "section": "service", "who": "reader", "text": "Зачем бедного обижаешь, плату работника удерживаешь, брата своего не любишь, к блуду и гордыне стремишься? Оставь же все это, душа моя, и покайся ради Царствия Божия!"},
  {"id": "ru-mol-0160", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. О, безумный человече, доколе углебаеши, яко пчела, собирающи богатство твое? Вскоре бо погибнет, яко прах и пепел: но более взыщи Царствия Божия."},
  {"id": "ru-mol-0161", "section": "service", "who": "reader", "text": "О безумный человек! Доколе будешь суетиться, словно пчела, собирая богатство своё? Ведь вскоре погибнет оно, как прах и пепел; но ты прежде взыщи Царствия Божия."},
  {"id": "ru-mol-0162", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Госпоже Богородице, помилуй мя грешную, и в добродетели укрепи, и соблюди мя, да наглая смерть не похитит мя неготовую, и доведи мя, Дево, Царствия Божия."},
  {"id": "ru-mol-0163", "section": "service", "who": "reader", "text": "Госпожа Богородица! Помилуй меня, грешную, и в добродетели укрепи и сохрани меня, чтобы внезапная смерть не похитила меня, неготовую, и доведи меня, Дева, до Царствия Божия!"},
  {"id": "ru-mol-0164", "section": "service", "who": "rubric", "text": "Песнь 5"},
  {"id": "ru-mol-0165", "section": "service", "who": "rubric", "text": "Ирмос: Божиим светом Твоим, Блаже, утренюющих Ти души любовию озари, молюся, Тя ведети, Слове Божий, истиннаго Бога, от мрака греховнаго взывающа."},
  {"id": "ru-mol-0166", "section": "service", "who": "reader", "text": "Божественным светом Своим, Благой, души с рассвета к Тебе стремящихся любовью озари, молюсь я, чтобы знать Тебя, Слово Божие, истинного Бога, от мрака грехов к Себе призывающего."},
  {"id": "ru-mol-0167", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0168", "section": "service", "who": "rubric", "text": "Воспомяни, окаянный человече, како лжам, клеветам, разбою, немощем, лютым зверем, грехов ради порабощен еси; душе моя грешная, того ли восхотела еси?"},
  {"id": "ru-mol-0169", "section": "service", "who": "reader", "text": "Вспомни, окаянный человек, как лжи, клевете, разбою, болезням, словно лютым зверям, порабощён ты по грехам своим! Душа моя грешная, того ли желала ты?"},
  {"id": "ru-mol-0170", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0171", "section": "service", "who": "rubric", "text": "Трепещут ми уди, всеми бо сотворих вину: очима взирающая, ушима слышащая, языком злая глаголющая, всю себе геенне предаяющая; душе моя грешная, сего ли восхотела еси?"},
  {"id": "ru-mol-0172", "section": "service", "who": "reader", "text": "Трепещут члены тела моего, ибо я всеми ими провинилась: глазами взирая, ушами слушая, языком говоря злое, всю себя геенне предала! Душа моя грешная, этого ли желала ты?"},
  {"id": "ru-mol-0173", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Блудника и разбойника кающася приял еси, Спасе, аз же едина леностию греховною отягчихся и злым делом поработихся, душе моя грешная, сего ли восхотела еси?"},
  {"id": "ru-mol-0174", "section": "service", "who": "reader", "text": "Блудного сына и разбойника кающегося принял Ты, Спаситель; но лишь я одна греховной ленью отягчена и злым делам порабощена! Душа моя грешная, этого ли желала ты?"},
  {"id": "ru-mol-0175", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Дивная и скорая помощнице всем человеком, Мати Божия, помози мне недостойной, душа бо моя грешная того восхоте."},
  {"id": "ru-mol-0176", "section": "service", "who": "reader", "text": "Дивная и скорая помощница всем людям, Матерь Божия! Помоги мне, недостойной, ибо душа моя грешная того возжелала!"},
  {"id": "ru-mol-0177", "section": "service", "who": "rubric", "text": "Песнь 6"},
  {"id": "ru-mol-0178", "section": "service", "who": "rubric", "text": "Ирмос: Житейское море, воздвизаемое зрящи напастей бурею, к тихому пристанищу Твоему притекши, вопию Ти: возведи от тли живот мой, Многомилостиве."},
  {"id": "ru-mol-0179", "section": "service", "who": "reader", "text": "Житейское море видя, поднимающееся волнами искушений, я, к тихой пристани Твоей стремясь, взываю Тебе: «Возведи от погибели жизнь мою, Многомилостивый!»"},
  {"id": "ru-mol-0180", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0181", "section": "service", "who": "rubric", "text": "Житие на земли блудно пожих и душу во тьму предах, ныне убо молю Тя, Милостивый Владыко: свободи мя от работы сея вражия, и даждь ми разум творити волю Твою."},
  {"id": "ru-mol-0182", "section": "service", "who": "reader", "text": "Жизнь земную я блудно прожила и душу во тьму предала; ныне же молю Тебя, милостивый Владыка: освободи меня от этого рабства врагу и дай мне разум исполнять волю Твою!"},
  {"id": "ru-mol-0183", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0184", "section": "service", "who": "rubric", "text": "Кто творит таковая, якоже аз? Якоже бо свиния лежит в калу, тако и аз греху служу. Но Ты, Господи, исторгни мя от гнуса сего и даждь ми сердце творити заповеди Твоя."},
  {"id": "ru-mol-0185", "section": "service", "who": "reader", "text": "Кто совершает такое, как я? Ибо как свинья лежит в грязи, так же и я греху служу. Но Ты, Господи, исторгни меня из гнусности той и дай мне сердце, готовое исполнять заповеди Твои!"},
  {"id": "ru-mol-0186", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Воспряни, окаянный человече, к Богу, воспомянув своя согрешения, припадая ко Творцу, слезя и стеня; Той же, яко милосерд, даст ти ум знати волю Свою."},
  {"id": "ru-mol-0187", "section": "service", "who": "reader", "text": "Воспрянь к Богу, окаянный человек, вспомнив свои согрешения, припадая ко Творцу, проливая слезы и стеная! Он же, как милосердный, даст тебе ум познать волю Его!"},
  {"id": "ru-mol-0188", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Богородице Дево, от видимаго и невидимаго зла сохрани мя, Пречистая, и приими молитвы моя, и донеси я Сыну Твоему, да даст ми ум творити волю Его."},
  {"id": "ru-mol-0189", "section": "service", "who": "reader", "text": "Богородица Дева! От видимого и невидимого зла сохрани меня, Пречистая, и прими прошения мои, и передай их Сыну Твоему, да даст мне ум исполнять волю Его!"},
  {"id": "ru-mol-0190", "section": "service", "who": "rubric", "text": "Кондак"},
  {"id": "ru-mol-0191", "section": "service", "who": "rubric", "text": "Душе моя, почто грехами богатееши, почто волю диаволю твориши, в чесом надежду полагаеши? Престани от сих и обратися к Богу с плачем, зовущи: милосерде Господи, помилуй мя грешную."},
  {"id": "ru-mol-0192", "section": "service", "who": "reader", "text": "Душа моя! Зачем грехами богатеешь? Зачем волю диавола исполняешь? На что надежду возлагаешь? Перестань так поступать и обратись к Богу, с плачем взывая: «Милосердный Господи, помилуй меня, грешную!»"},
  {"id": "ru-mol-0193", "section": "service", "who": "rubric", "text": "Икос"},
  {"id": "ru-mol-0194", "section": "service", "who": "rubric", "text": "Помысли, душе моя, горький час смерти и страшный суд Творца твоего и Бога: Ангели бо грознии поймут тя, душе, и в вечный огнь введут: убо прежде смерти покайся, вопиющи: Господи, помилуй мя грешную."},
  {"id": "ru-mol-0195", "section": "service", "who": "reader", "text": "Помысли, душа моя, о горьком часе смерти и о Страшном Суде Творца твоего и Бога. Ведь тогда Ангелы грозные возьмут тебя, душа, и в вечный огонь введут. Так покайся же прежде смерти, взывая: «Господи, помилуй меня, грешную!»"},
  {"id": "ru-mol-0196", "section": "service", "who": "rubric", "text": "Песнь 7"},
  {"id": "ru-mol-0197", "section": "service", "who": "rubric", "text": "Ирмос: Росодательну убо пещь содела Ангел преподобным отроком, халдеи же опаляющее веление Божие, мучителя увеща вопити: благословен еси, Боже отец наших."},
  {"id": "ru-mol-0198", "section": "service", "who": "reader", "text": "Росоносною соделал печь Ангел для благочестивых отроков, а Божие веление, халдеев опалявшее, мучителя заставило взывать: «Благословен Ты, Боже отцов наших!»"},
  {"id": "ru-mol-0199", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0200", "section": "service", "who": "rubric", "text": "Не надейся, душе моя, на тленное богатство и на неправедное собрание, вся бо сия не веси кому оставиши, но возопий: помилуй мя, Христе Боже, недостойную."},
  {"id": "ru-mol-0201", "section": "service", "who": "reader", "text": "Не полагайся, душа моя, на тленное богатство и на неправедное стяжание; ведь не знаешь ты, кому всё это оставишь, но воззови: «Помилуй меня, Христе Боже, недостойную!»"},
  {"id": "ru-mol-0202", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0203", "section": "service", "who": "rubric", "text": "Не уповай, душе моя, на телесное здравие и на скоромимоходящую красоту, видиши бо, яко сильнии и младии умирают; но возопий: помилуй мя, Христе Боже, недостойную."},
  {"id": "ru-mol-0204", "section": "service", "who": "reader", "text": "Не надейся, душа моя, на телесное здоровье и на скоро преходящую красоту; ведь ты видишь, как сильные и молодые умирают, но воззови: «Помилуй меня, Христе Боже, недостойную!»"},
  {"id": "ru-mol-0205", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Воспомяни, душе моя, вечное житие, Царство Небесное, уготованное святым, и тьму кромешную и гнев Божий злым, и возопий: помилуй мя, Христе Боже, недостойную."},
  {"id": "ru-mol-0206", "section": "service", "who": "reader", "text": "Вспомни, душа моя, о вечной жизни и о Царстве Небесном, уготованном святым, и о тьме кромешной и гневе Божием – злым, и воззови: «Помилуй меня, Христе Боже, недостойную!»"},
  {"id": "ru-mol-0207", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Припади, душе моя, к Божией Матери и помолися Той, есть бо скорая помощница кающимся, умолит Сына Христа Бога, и помилует мя недостойную."},
  {"id": "ru-mol-0208", "section": "service", "who": "reader", "text": "Припади, душа моя, к Божией Матери и помолись Ей, ибо Она, скорая Помощница кающимся, умолит Сына, Христа Бога, и Он помилует меня, недостойную."},
  {"id": "ru-mol-0209", "section": "service", "who": "rubric", "text": "Песнь 8"},
  {"id": "ru-mol-0210", "section": "service", "who": "rubric", "text": "Ирмос: Из пламене преподобным росу источил еси и праведнаго жертву водою попалил еси: вся бо твориши, Христе, токмо еже хотети. Тя превозносим во вся веки."},
  {"id": "ru-mol-0211", "section": "service", "who": "reader", "text": "Из пламени Ты для благочестивых росу источил, и жертву праведника водою попалил: ибо Ты все совершаешь, Христе, одним Своим хотением. Тебя мы превозносим во все века."},
  {"id": "ru-mol-0212", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0213", "section": "service", "who": "rubric", "text": "Како не имам плакатися, егда помышляю смерть, видех бо во гробе лежаща брата моего, безславна и безобразна? Что убо чаю, и на что надеюся? Токмо даждь ми, Господи, прежде конца покаяние. (Дважды)"},
  {"id": "ru-mol-0214", "section": "service", "who": "reader", "text": "Как мне не плакать, когда помышляю о смерти! Ибо видела я лежащего во гробе брата своего бесславным и безобразным. Чего же я жду и на что надеюсь? Только дай мне, Господи, прежде конца покаяние!"},
  {"id": "ru-mol-0215", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Верую, яко приидеши судити живых и мертвых, и вси во своем чину станут, старии и младии, владыки и князи, девы и священницы; где обрящуся аз? Сего ради вопию: даждь ми, Господи, прежде конца покаяние."},
  {"id": "ru-mol-0216", "section": "service", "who": "reader", "text": "Верую, что Ты придёшь судить живых и мёртвых, и все по чину своему станут: старые и молодые, владыки и князья, девы и священники. Но где окажусь я? Потому взываю: «Дай мне, Господи, прежде конца покаяние!»"},
  {"id": "ru-mol-0217", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Пречистая Богородице, приими недостойную молитву мою и сохрани мя от наглыя смерти, и даруй ми прежде конца покаяние."},
  {"id": "ru-mol-0218", "section": "service", "who": "reader", "text": "Пречистая Богородица! Прими недостойную молитву мою, и сохрани меня от внезапной смерти и даруй мне прежде конца покаяние!"},
  {"id": "ru-mol-0219", "section": "service", "who": "rubric", "text": "Песнь 9"},
  {"id": "ru-mol-0220", "section": "service", "who": "rubric", "text": "Ирмос: Бога человеком невозможно видети, на Негоже не смеют чини Ангельстии взирати; Тобою же, Всечистая, явися человеком Слово Воплощенно, Егоже величающе, с небесными вои Тя ублажаем."},
  {"id": "ru-mol-0221", "section": "service", "who": "reader", "text": "Невозможно людям увидеть Бога, на Которого не смеют и сонмы Ангелов взирать; но чрез Тебя, Всечистая, стало видимым для смертных Слово воплощённое. Его величая, мы вместе с небесными воинствами Тебя восхваляем."},
  {"id": "ru-mol-0222", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0223", "section": "service", "who": "rubric", "text": "Ныне к вам прибегаю, Ангели, Архангели и вся небесныя силы, у Престола Божия стоящии, молитеся ко Творцу своему, да избавит душу мою от муки вечныя."},
  {"id": "ru-mol-0224", "section": "service", "who": "reader", "text": "Ныне к вам прибегаю, Ангелы, Архангелы и все небесные Силы, у престола Божия стоящие: молитесь Творцу своему, да избавит Он душу мою от муки вечной!"},
  {"id": "ru-mol-0225", "section": "service", "who": "rubric", "text": "Помилуй мя, Боже, помилуй мя."},
  {"id": "ru-mol-0226", "section": "service", "who": "rubric", "text": "Ныне плачуся к вам, святии патриарси, царие и пророцы, апостоли и святителие и вси избраннии Христовы: помозите ми на суде, да спасет душу мою от силы вражия."},
  {"id": "ru-mol-0227", "section": "service", "who": "reader", "text": "Ныне плачу пред вами, святые праотцы, цари и пророки, апостолы и святители, и все избранники Христовы: помогите мне на Суде, да спасет Господь душу мою от силы вражией!"},
  {"id": "ru-mol-0228", "section": "service", "who": "rubric", "text": "Слава Отцу, и Сыну, и Святому Духу. Ныне к вам воздежу руце, святии мученицы, пустынницы, девственницы, праведницы и вси святии, молящиися ко Господу за весь мир, да помилует мя в час смерти моея."},
  {"id": "ru-mol-0229", "section": "service", "who": "reader", "text": "Ныне к вам возношу руки, святые мученики, пустынники, девственники, праведники и все святые, молящиеся ко Господу за весь мир, да помилует Он меня в час смерти моей!"},
  {"id": "ru-mol-0230", "section": "service", "who": "rubric", "text": "И ныне, и присно, и во веки веков, аминь. Мати Божия, помози ми, на Тя сильне надеющейся, умоли Сына Своего, да поставит мя недостойную одесную Себе, егда сядет судяй живых и мертвых, аминь."},
  {"id": "ru-mol-0231", "section": "service", "who": "reader", "text": "Матерь Божия, помоги мне, на Тебя крепко надеющейся, умоли Сына Своего, да поставит Он меня, недостойную, справа от Себя, когда сядет судить живых и мёртвых! Аминь."},
  {"id": "ru-mol-0232", "section": "service", "who": "rubric", "text": "Молитва"},
  {"id": "ru-mol-0233", "section": "service", "who": "reader", "text": "Владыка Христос Бог, страданиями Твоими страсти мои исцеливший и ранами Твоими язвы мои уврачевавший! Даруй мне, много пред Тобою согрешившей, слёзы сокрушения о грехах. Даруй моему телу принять благоухание животворящего Тела Твоего, и подай душе моей сладость Твоей драгоценной Крови вместо горечи, которой напоил меня враг. Возвысь к Тебе мой ум, к земле поникший, и возведи из пропасти погибельной. Ибо нет во мне покаяния, нет во мне сокрушения, нет во мне слёз утешительных, приводящих чад к Отчему дому. Омрачилась я разумом в житейских страстях, не могу воззреть на Тебя в страдании, не могу согреться слезами любви к Тебе! Но, Владыка Господь Иисус Христос, Сокровищница благ! Даруй мне покаяние полное и сердце, с любовью трудящееся в поисках Тебя; даруй мне благодать Твою и обнови во мне черты Твоего образа. Я оставила Тебя — не оставь меня. Выйди искать меня, приведи на Своё пастбище и сопричисли меня к овцам Твоего избранного стада, напитай меня вместе с ними от хлеба Божественных Твоих Таинств, по молитвам Пречистой Твоей Матери и всех святых Твоих. Аминь."},
  {"id": "ru-mol-0234", "section": "service", "who": "rubric", "text": "Рекомендуем молитвы"},
  {"id": "ru-mol-0235", "section": "service", "who": "rubric", "text": "116 комментариев"},
  {"id": "ru-mol-0236", "section": "service", "who": "rubric", "text": "Православное радио"},
  {"id": "ru-mol-0237", "section": "service", "who": "rubric", "text": "Сейчас в разделе 6741 чел."},
  {"id": "ru-mol-0238", "section": "service", "who": "rubric", "text": "Просмотров 620 млн."},
  {"id": "ru-mol-0239", "section": "service", "who": "rubric", "text": "Молитвословий 2014"},
  {"id": "ru-mol-0240", "section": "service", "who": "rubric", "text": "Пожертвовать"},
  {"id": "ru-mol-0241", "section": "service", "who": "rubric", "text": "©2026 Молитвослов"},
];

